css:
/*
 * ============================================================
 * TRANSPARENCIA DEL DOCUMENTO INTERNO
 * ============================================================
 *
 * PsiCore introduce normalmente una regla semejante a:
 *
 * body {
 *   background: var(--w-bg);
 * }
 *
 * Por eso se sobrescribe tanto la variable --w-bg como todos
 * los posibles contenedores internos.
 */

:root {
  --w-bg: rgba(0, 0, 0, 0) !important;

  background: none !important;
  background-color: rgba(0, 0, 0, 0) !important;
  background-image: none !important;

  box-shadow: none !important;
}

/*
 * Documento, cuerpo y posibles raíces creadas por PsiCore.
 */
html,
body,
#root,
#app,
#__next,
.widget-root,
.widget-container,
.pid-pulley-widget,
.pid-diagram {
  background: none !important;
  background-color: rgba(0, 0, 0, 0) !important;
  background-image: none !important;
  background-repeat: no-repeat !important;

  box-shadow: none !important;

  border: 0 !important;
  outline: 0 !important;
}

/*
 * El documento interno debe ocupar exactamente el tamaño
 * del iframe, sin márgenes ni rellenos.
 */
html,
body {
  width: 100%;
  height: 100%;

  min-width: 0;
  min-height: 0;

  margin: 0 !important;
  padding: 0 !important;

  overflow: hidden;

  border-radius: 0 !important;
}

/*
 * Elimina capas que pudieran dibujarse mediante
 * pseudoelementos.
 */
html::before,
html::after,
body::before,
body::after,
#root::before,
#root::after,
#app::before,
#app::after,
.pid-pulley-widget::before,
.pid-pulley-widget::after {
  content: none !important;
  display: none !important;

  background: none !important;
  background-color: rgba(0, 0, 0, 0) !important;
  background-image: none !important;

  box-shadow: none !important;
}

/*
 * Elimina cualquier propiedad CSS de fondo heredada por los
 * elementos internos.
 *
 * Esto no afecta a los colores SVG aplicados mediante fill
 * o stroke.
 */
.pid-pulley-widget,
.pid-pulley-widget * {
  background: none !important;
  background-color: rgba(0, 0, 0, 0) !important;
  background-image: none !important;

  box-shadow: none !important;
}

/*
 * ============================================================
 * CONTENEDOR PRINCIPAL
 * ============================================================
 */

.pid-pulley-widget {
  width: 100%;
  height: 100%;

  display: grid;
  place-items: center;

  position: relative;

  margin: 0 !important;
  padding: 0 !important;

  overflow: hidden;

  border-radius: 0 !important;
}

/*
 * El SVG ocupa todo el espacio disponible.
 *
 * preserveAspectRatio="xMidYMid meet", definido en el HTML,
 * evita que se deformen las poleas.
 */
.pid-diagram {
  display: block;

  width: 100%;
  height: 100%;

  max-width: 100%;
  max-height: 100%;

  margin: 0 !important;
  padding: 0 !important;

  overflow: visible;

  border-radius: 0 !important;

  /*
   * No se utiliza ningún relleno para el elemento SVG raíz.
   */
  fill: none;
}

/*
 * ============================================================
 * CUBA
 * ============================================================
 *
 * Este fill se limita a la figura de la cuba. No es un fondo
 * general del widget.
 */

.bath-shell {
  fill: rgba(178, 179, 207, 0.16);

  stroke: #3e4148;
  stroke-width: 5;
}

.bath-liquid {
  opacity: 0.98;
}

.wave-line {
  fill: none;

  stroke: #4d526a;
  stroke-width: 2.2;
}

.bath-rim,
.bath-base {
  fill: none;

  stroke: #32353b;
  stroke-width: 5;
}

/*
 * ============================================================
 * CUERDA O MATERIAL
 * ============================================================
 */

.web-outline {
  fill: none;

  stroke: #33363b;
  stroke-width: 7;

  stroke-linecap: round;
  stroke-linejoin: round;
}

.web-rope {
  fill: none;

  stroke: #78804e;
  stroke-width: 3.4;

  stroke-linecap: round;
  stroke-linejoin: round;
}

/*
 * ============================================================
 * POLEAS
 * ============================================================
 */

.pulley-body {
  fill: #a9a9c8;

  stroke: #30333a;
  stroke-width: 5;
}

.pulley-inner {
  fill: rgba(198, 198, 222, 0.45);

  stroke: rgba(255, 255, 255, 0.2);
  stroke-width: 2;
}

.pulley-shaft {
  fill: none;

  stroke: #30333a;
  stroke-width: 4;
}

.pulley-hub {
  fill: #4b4f59;
}

/*
 * ============================================================
 * TUBERÍAS P&ID
 * ============================================================
 */

.process-pipe {
  fill: none;

  stroke: #45494f;
  stroke-width: 4;

  stroke-linecap: square;
  stroke-linejoin: miter;
}

/*
 * ============================================================
 * VÁLVULAS
 * ============================================================
 */

.valve-body,
.valve-actuator,
.manual-valve-body,
.manual-valve-center {
  fill: #e13e50;

  stroke: #9b2638;
  stroke-width: 2;
}

.valve-stem {
  fill: none;

  stroke: #9b2638;
  stroke-width: 3;
}

/*
 * ============================================================
 * INSTRUMENTACIÓN
 * ============================================================
 */

.instrument-body {
  fill: rgba(225, 239, 220, 0.5);

  stroke: #438252;
  stroke-width: 3;
}

.instrument-divider {
  fill: none;

  stroke: #438252;
  stroke-width: 2;
}

.impulse-line {
  fill: none;

  stroke: #438252;
  stroke-width: 3;
}

.signal-line {
  fill: none;

  stroke: #438252;
  stroke-width: 2.5;

  stroke-dasharray: 9 6;
}

/*
 * ============================================================
 * BOMBA
 * ============================================================
 */

.pump-body {
  fill: #40bd4f;

  stroke: #176e2b;
  stroke-width: 4;
}

.pump-slot,
.pump-base {
  fill: none;

  stroke: #176e2b;
  stroke-width: 3;
}
